-- ============================================================
-- V4: 품질설계결과(qualityDesignResult)·시뮬레이션(designSimulation)·공용 주문(qcdOrder) 표와 시연 데이터
-- ============================================================
--
-- 대상 스키마: MQCAPUSER   위치: mqc
-- 이 파일은 그 스키마 주인으로 접속해 실행된다(앱 Flyway 또는 pdb.mjs template-schema, 운영은 DBA).
--
-- 배경:
--   OMS 에서 받은 주문 줄(TB_MQC_ORD)마다 품질설계 의뢰(TB_MQC_DSN_REQ)가 하나 있고, 설계 계산(calculate)은 Maru 룰로
--   6단계 파이프라인(입력 검증 → 주문정합성 → 주문단중 → 생산가부 → 품질사양 매칭 → 설계값 산출)을 돌려 결과 문서를
--   TB_MQC_DSN_RSLT.RESULT_JSON 에 저장한다. 상태 변경은 TB_MQC_DSN_HIST 에 남긴다.
--   시뮬레이션 케이스(TB_MQC_SIM_CASE)는 같은 파이프라인을 회귀 시험으로 돌린다(기대값 pin·단계 판정·골든 스냅샷).
--   주문 키는 문자열(ORD_REQ_NO-ORD_REQ_LN, 예 D260831014-010)로만 잇고 다른 담당 표에 FK 를 걸지 않는다.
--   OMS 주문 항목 중 표 칼럼에 없는 것은 EXTRA_JSON(CLOB, {"항목":"값"})에 둔다.
--   고객명은 가명(수요가 A~H)이다. 고객 코드 → 가명은 V2 품질사양 고객 표와 같게 맞췄다(110197 A · 320104 B · 320100 C · 115462 D · 205202 E).
--   시연 데이터는 고정 값이다(의뢰일 2026-08-30~31). 설계결과(TB_MQC_DSN_RSLT)는 시드하지 않는다 — 화면이 계산 전 미리보기를 보인다.
-- 날짜만 담는 칼럼은 VARCHAR2(8) YYYYMMDD, 시각은 DATE(초 단위)다. 컬럼 순서 = PK → 엔티티 필드 선언 순서.
-- ============================================================

-- 주문 줄(OMS 수신). 시뮬레이션 orderFromSeed 의 정본 주문 모델 항목을 칼럼으로 둔다. 읽기 전용(시연에서는 시드만).
CREATE TABLE TB_MQC_ORD (
    ORD_REQ_NO           VARCHAR2(20 CHAR)   NOT NULL,
    ORD_REQ_LN           VARCHAR2(5 CHAR)    NOT NULL,
    PRD_NM_CD            VARCHAR2(2 CHAR)    NOT NULL,
    PRD_SHP              VARCHAR2(2 CHAR),
    SPC_AVR              VARCHAR2(30 CHAR),
    MAT_CD               VARCHAR2(5 CHAR),
    ORD_EXC_THK          NUMBER(6,3),
    ORD_EXC_WTH          NUMBER(7,1),
    FNL_CUS_CD           VARCHAR2(10 CHAR),
    FNL_CUS_NM           VARCHAR2(50 CHAR),
    ORD_USG_CD           VARCHAR2(10 CHAR),
    ORD_USG_NM           VARCHAR2(50 CHAR),
    ORD_USG_DTL          VARCHAR2(100 CHAR),
    ORD_EDG_ASG_TP       VARCHAR2(2 CHAR),
    ORD_LN_WGT           NUMBER(7,1),
    ORD_SLIT_GRP_CNT     NUMBER(3),
    ORD_PAK_UNT_WGT_ULV  NUMBER(7),
    ORD_PAK_UNT_WGT_LLV  NUMBER(7),
    ORD_PTT_FLM_CD       VARCHAR2(10 CHAR),
    ORD_SLV_KND_TP       VARCHAR2(2 CHAR),
    FLOW_CHL             VARCHAR2(5 CHAR),
    NAT_CD               VARCHAR2(5 CHAR),
    ORD_KND              VARCHAR2(5 CHAR),
    CUS_CD               VARCHAR2(10 CHAR),
    ACT_CUS_CD           VARCHAR2(10 CHAR),
    SPC_YR               VARCHAR2(4 CHAR),
    ORD_SZ               VARCHAR2(40 CHAR),
    ORD_THK_TP           VARCHAR2(2 CHAR),
    WGT_DCS_MTH_TP       VARCHAR2(5 CHAR),
    ORD_WGT_UNT          VARCHAR2(5 CHAR),
    ORD_PAK_MTH          VARCHAR2(10 CHAR),
    ORD_THK_MNG_CD       VARCHAR2(2 CHAR),
    ORD_WTH_MNG_CD       VARCHAR2(2 CHAR),
    ORD_RGS_PRS_ID       VARCHAR2(20 CHAR),
    ORD_TEM_CD           VARCHAR2(10 CHAR),
    ORD_COIL_IDIA        NUMBER(5),
    ORD_COILG_MTH        VARCHAR2(2 CHAR),
    GW_ASG_CD            VARCHAR2(5 CHAR),
    CCL_BOM_NO           VARCHAR2(10 CHAR),
    ORD_SPNL_TP          VARCHAR2(2 CHAR),
    URGENT_YN            VARCHAR2(1 CHAR)    NOT NULL,
    REQ_DT               VARCHAR2(8 CHAR)    NOT NULL,
    SRC_TP               VARCHAR2(10 CHAR)   NOT NULL,
    RECV_DTTM            DATE,
    EXTRA_JSON           CLOB,
    CONSTRAINT PK_MQC_ORD PRIMARY KEY (ORD_REQ_NO, ORD_REQ_LN),
    CONSTRAINT CK_MQC_ORD_URGENT CHECK (URGENT_YN IN ('Y', 'N'))
);
CREATE INDEX IX_MQC_ORD_REQ_DT ON TB_MQC_ORD (REQ_DT);
COMMENT ON TABLE TB_MQC_ORD IS 'OMS 주문 줄(품질설계 대상)';
COMMENT ON COLUMN TB_MQC_ORD.FNL_CUS_NM IS '최종수요가 가명(시연)';
COMMENT ON COLUMN TB_MQC_ORD.REQ_DT IS '설계 의뢰일 YYYYMMDD';
COMMENT ON COLUMN TB_MQC_ORD.EXTRA_JSON IS '표 칼럼에 없는 OMS 주문 항목 {"항목":"값"}';

-- 품질설계 의뢰(주문 줄당 하나). 상태 WAIT 미설계 → ING 설계중 → CONF 확정, 아무 상태 ↔ HOLD 보류(PREV_STAT 로 되돌림).
CREATE TABLE TB_MQC_DSN_REQ (
    ORD_KEY      VARCHAR2(30 CHAR)   NOT NULL,
    ORD_REQ_NO   VARCHAR2(20 CHAR)   NOT NULL,
    ORD_REQ_LN   VARCHAR2(5 CHAR)    NOT NULL,
    REQ_DT       VARCHAR2(8 CHAR)    NOT NULL,
    DSN_STAT     VARCHAR2(10 CHAR)   NOT NULL,
    PREV_STAT    VARCHAR2(10 CHAR),
    CONF_BY      VARCHAR2(50 CHAR),
    CONF_DTTM    DATE,
    MOD_BY       VARCHAR2(50 CHAR)   NOT NULL,
    MOD_DTTM     DATE                NOT NULL,
    CONSTRAINT PK_MQC_DSN_REQ PRIMARY KEY (ORD_KEY),
    CONSTRAINT CK_MQC_DSN_REQ_STAT CHECK (DSN_STAT IN ('WAIT', 'ING', 'CONF', 'HOLD')),
    CONSTRAINT CK_MQC_DSN_REQ_PREV CHECK (PREV_STAT IS NULL OR PREV_STAT IN ('WAIT', 'ING', 'CONF'))
);
CREATE INDEX IX_MQC_DSN_REQ_DT ON TB_MQC_DSN_REQ (REQ_DT);
COMMENT ON TABLE TB_MQC_DSN_REQ IS '품질설계 의뢰(주문 줄당 설계 상태)';
COMMENT ON COLUMN TB_MQC_DSN_REQ.ORD_KEY IS '주문 키 ORD_REQ_NO-ORD_REQ_LN';
COMMENT ON COLUMN TB_MQC_DSN_REQ.PREV_STAT IS '보류 전 상태(보류 해제 때 되돌린다)';

-- 설계결과: 파이프라인 실행 문서 하나(RESULT_JSON = 단계 6개·설계값·근거·형상·이상징후)와 머리 칼럼.
CREATE TABLE TB_MQC_DSN_RSLT (
    ORD_KEY      VARCHAR2(30 CHAR)   NOT NULL,
    VERDICT      VARCHAR2(5 CHAR)    NOT NULL,
    MAIN_LINE    VARCHAR2(10 CHAR),
    ROUTE_CD     VARCHAR2(30 CHAR),
    RAW_MAT_CD   VARCHAR2(10 CHAR),
    SET_THK      NUMBER(6,3),
    PLTCM_WID    NUMBER(7,1),
    ERR_CNT      NUMBER(5)           NOT NULL,
    WARN_CNT     NUMBER(5)           NOT NULL,
    EVAL_DTTM    DATE                NOT NULL,
    RESULT_JSON  CLOB                NOT NULL,
    CALC_BY      VARCHAR2(50 CHAR)   NOT NULL,
    CALC_DTTM    DATE                NOT NULL,
    CONSTRAINT PK_MQC_DSN_RSLT PRIMARY KEY (ORD_KEY),
    CONSTRAINT CK_MQC_DSN_RSLT_VERDICT CHECK (VERDICT IN ('OK', 'WARN', 'BLOCK'))
);
COMMENT ON TABLE TB_MQC_DSN_RSLT IS '품질설계결과(파이프라인 실행 문서)';
COMMENT ON COLUMN TB_MQC_DSN_RSLT.RESULT_JSON IS '{stages, design, shape, anomalies, source, ...} — 화면 계약 PipelineRun';

-- 설계 이력: 계산·확정·보류·보류 해제.
CREATE TABLE TB_MQC_DSN_HIST (
    HIST_ID      NUMBER(19)          GENERATED BY DEFAULT AS IDENTITY,
    ORD_KEY      VARCHAR2(30 CHAR)   NOT NULL,
    ACTION_CD    VARCHAR2(10 CHAR)   NOT NULL,
    BEFORE_STAT  VARCHAR2(10 CHAR),
    AFTER_STAT   VARCHAR2(10 CHAR)   NOT NULL,
    NOTE         VARCHAR2(500 CHAR),
    ACT_BY       VARCHAR2(50 CHAR)   NOT NULL,
    ACT_DTTM     DATE                NOT NULL,
    CONSTRAINT PK_MQC_DSN_HIST PRIMARY KEY (HIST_ID),
    CONSTRAINT CK_MQC_DSN_HIST_ACTION CHECK (ACTION_CD IN ('CALC', 'CONF', 'HOLD', 'UNHOLD'))
);
CREATE INDEX IX_MQC_DSN_HIST_KEY ON TB_MQC_DSN_HIST (ORD_KEY);
COMMENT ON TABLE TB_MQC_DSN_HIST IS '품질설계 상태·계산 이력';

-- 시뮬레이션 케이스: 주문(JSON)·기대값 pin·단계 판정 기대·골든 스냅샷·마지막 실행.
CREATE TABLE TB_MQC_SIM_CASE (
    CASE_ID        VARCHAR2(20 CHAR)    NOT NULL,
    CASE_NM        VARCHAR2(100 CHAR)   NOT NULL,
    BASE_ORD_REF   VARCHAR2(30 CHAR),
    ORDER_JSON     CLOB                 NOT NULL,
    PINS_JSON      CLOB,
    VERDICTS_JSON  CLOB,
    GOLDEN_JSON    CLOB,
    GOLDEN_DTTM    DATE,
    LAST_STAT      VARCHAR2(10 CHAR)    NOT NULL,
    LAST_RUN_JSON  CLOB,
    LAST_RUN_DTTM  DATE,
    AUTHOR_NM      VARCHAR2(50 CHAR)    NOT NULL,
    REG_DTTM       DATE                 NOT NULL,
    MOD_DTTM       DATE                 NOT NULL,
    CONSTRAINT PK_MQC_SIM_CASE PRIMARY KEY (CASE_ID),
    CONSTRAINT CK_MQC_SIM_CASE_STAT CHECK (LAST_STAT IN ('NOT_RUN', 'PASS', 'WARN', 'FAIL'))
);
COMMENT ON TABLE TB_MQC_SIM_CASE IS '품질설계 시뮬레이션(회귀) 케이스';
COMMENT ON COLUMN TB_MQC_SIM_CASE.PINS_JSON IS '[{path,label,op(= ~ ≠),val}]';
COMMENT ON COLUMN TB_MQC_SIM_CASE.VERDICTS_JSON IS '[{stage,expect} 또는 {stage,expectErrorCode}]';
COMMENT ON COLUMN TB_MQC_SIM_CASE.GOLDEN_JSON IS '설계결과 평탄화 스냅샷 {경로:값}';
COMMENT ON COLUMN TB_MQC_SIM_CASE.LAST_RUN_JSON IS '마지막 실행 평가 CaseEval';

